@push('scripts')
<script src="https://cdn.jsdelivr.net/npm/livekit-client@2.15.7/dist/livekit-client.umd.min.js"></script>
<script>
(() => {
    const entrada=document.getElementById('entrada'), sala=document.getElementById('sala'), form=document.getElementById('formEntrada'), erro=document.getElementById('erroEntrada'), configuracao=document.getElementById('configuracaoLiveKit'), verConfiguracao=document.getElementById('verConfiguracao'), palco=document.getElementById('palco'), vazio=document.getElementById('palcoVazio'), status=document.getElementById('statusSala');
    const botoes={camera:document.getElementById('camera'),microfone:document.getElementById('microfone'),tela:document.getElementById('tela'),sair:document.getElementById('sair')}; let room, camera=true, microfone=true, tela=false;
    const csrf='{{ csrf_token() }}';
    const mostrarErro=(texto,exibirConfiguracao=false)=>{erro.replaceChildren(document.createTextNode(texto));if(/could not establish pc connection/i.test(texto)){const recomendacao=document.createElement('span');recomendacao.className='ms-1';recomendacao.textContent='Recomendamos utilizar o Google Chrome para entrar na sala.';erro.append(recomendacao)}erro.classList.remove('d-none');verConfiguracao.classList.toggle('d-none',!exibirConfiguracao)};
    const idTile=(participante, publicacao)=>`tile-${participante.identity}-${publicacao.trackSid||publicacao.sid||publicacao.source}`.replace(/[^a-zA-Z0-9_-]/g,'_');
    function mostrarTrack(track, publicacao, participante){const id=idTile(participante,publicacao);if(document.getElementById(id))return;if(track.kind==='audio'){if(participante.isLocal)return;const audio=track.attach();audio.id=id;audio.autoplay=true;document.getElementById('audioRemoto').append(audio);return}if(track.kind!=='video')return;vazio?.remove();const tile=document.createElement('div');tile.className='sala-tile';tile.id=id;const video=track.attach();video.autoplay=true;video.playsInline=true;if(participante.isLocal)video.muted=true;tile.append(video);const nome=document.createElement('span');nome.className='sala-tile__nome';nome.textContent=`${participante.name||'Participante'}${publicacao.source==='screen_share'?' — tela':''}`;tile.append(nome);palco.append(tile)}
    function removerTrack(publicacao, participante){document.getElementById(idTile(participante,publicacao))?.remove();if(!palco.querySelector('.sala-tile'))palco.append(vazio||Object.assign(document.createElement('div'),{className:'sala-vazia',textContent:'Aguardando câmeras e compartilhamentos de tela.'}))}
    function atualizarControles(){botoes.camera.innerHTML=`<i class="bi bi-camera-video${camera?'':'-off'} me-1"></i>${camera?'Desligar câmera':'Ligar câmera'}`;botoes.microfone.innerHTML=`<i class="bi bi-mic${microfone?'':'-mute'} me-1"></i>${microfone?'Silenciar':'Ligar microfone'}`;botoes.tela.innerHTML=`<i class="bi bi-display me-1"></i>${tela?'Parar compartilhamento':'Compartilhar tela'}`}
    async function entrar(nome){const resposta=await fetch('{{ route('transmissoes.entrar', ['transmissao' => $transmissao->hash_publico]) }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({nome})});const dados=await resposta.json();if(!resposta.ok)throw Object.assign(new Error(dados.message||'Não foi possível entrar na sala.'),{configuracao:!!dados.configuracao});room=new LivekitClient.Room();room.on(LivekitClient.RoomEvent.TrackSubscribed,mostrarTrack);room.on(LivekitClient.RoomEvent.TrackUnsubscribed,removerTrack);room.on(LivekitClient.RoomEvent.TrackPublished,(pub,participante)=>{if(pub.track)mostrarTrack(pub.track,pub,participante)});room.on(LivekitClient.RoomEvent.ParticipantDisconnected,(participante)=>{document.querySelectorAll(`[id^="tile-${participante.identity.replace(/[^a-zA-Z0-9_-]/g,'_')}-"]`).forEach(e=>e.remove())});room.on(LivekitClient.RoomEvent.Disconnected,()=>{status.textContent='Você saiu da sala.'});await room.connect(dados.url,dados.token);await room.localParticipant.setCameraEnabled(true);await room.localParticipant.setMicrophoneEnabled(true);room.localParticipant.trackPublications.forEach(pub=>{if(pub.track)mostrarTrack(pub.track,pub,room.localParticipant)});status.textContent='Conectado. Sua câmera e seu microfone estão ativos.';entrada.classList.add('d-none');sala.classList.remove('d-none');atualizarControles()}
    form.addEventListener('submit',async e=>{e.preventDefault();erro.classList.add('d-none');const botao=form.querySelector('button[type="submit"]');botao.disabled=true;try{await entrar(document.getElementById('nome').value.trim())}catch(ex){mostrarErro(ex.message,ex.configuracao);botao.disabled=false}});verConfiguracao.addEventListener('click',()=>{const oculto=configuracao.classList.toggle('d-none');verConfiguracao.textContent=oculto?'Ver configuração':'Ocultar configuração';verConfiguracao.setAttribute('aria-expanded',String(!oculto))});
    botoes.camera.addEventListener('click',async()=>{camera=!camera;await room.localParticipant.setCameraEnabled(camera);atualizarControles()});botoes.microfone.addEventListener('click',async()=>{microfone=!microfone;await room.localParticipant.setMicrophoneEnabled(microfone);atualizarControles()});botoes.tela.addEventListener('click',async()=>{try{tela=!tela;await room.localParticipant.setScreenShareEnabled(tela);atualizarControles()}catch(ex){tela=false;atualizarControles();status.textContent='Não foi possível compartilhar a tela: '+ex.message}});botoes.sair.addEventListener('click',()=>{room?.disconnect();sala.classList.add('d-none');entrada.classList.remove('d-none')});
})();
</script>
@endpush
